-- Recordings library (docs/adr/0028-recordings-and-instant-replay.md).
--
-- One row per recording; the file itself lives under SUPERHET_RECORDINGS_DIR and is addressed by
-- `stem` (generated by the service, never user input). `state`:
--   recording    still being written
--   done         finished normally or by a limit
--   interrupted  the API restarted while it was being written (the file keeps what was written)
--   failed       could not be written
-- `keep` exempts a recording from the oldest-first quota cleanup. `meta` carries what does not
-- need a column: audio segments (gated recordings), RDS tags, IQ sample format, rate, hash,
-- completeness.
CREATE TABLE superhet.recordings (
    id          bigserial   PRIMARY KEY,
    kind        text        NOT NULL CHECK (kind IN ('audio', 'iq')),
    source      text        NOT NULL DEFAULT 'manual' CHECK (source IN ('manual', 'replay', 'scanner')),
    state       text        NOT NULL DEFAULT 'recording'
        CHECK (state IN ('recording', 'done', 'interrupted', 'failed')),
    stem        text        NOT NULL CHECK (stem ~ '^[A-Za-z0-9_-]{1,96}$'),
    title       text        NOT NULL DEFAULT '' CHECK (char_length(title) <= 200),
    device      text        NOT NULL CHECK (char_length(device) BETWEEN 1 AND 64),
    vfo         integer,
    freq_hz     bigint,
    mode        text,
    owner_name  text,
    owner_id    text,
    started_at  timestamptz NOT NULL DEFAULT now(),
    stopped_at  timestamptz,
    duration_ms bigint      NOT NULL DEFAULT 0,
    size_bytes  bigint      NOT NULL DEFAULT 0,
    keep        boolean     NOT NULL DEFAULT false,
    meta        jsonb       NOT NULL DEFAULT '{}'::jsonb
);

CREATE INDEX recordings_started_idx ON superhet.recordings (started_at DESC, id DESC);
CREATE INDEX recordings_device_idx  ON superhet.recordings (device, started_at DESC);
CREATE INDEX recordings_cleanup_idx ON superhet.recordings (started_at) WHERE state <> 'recording' AND NOT keep;

UPDATE superhet.schema_version SET version = 18, applied_at = now();
